#!/usr/bin/env node
// Generates the SDK-free copy maps the startup feature renders before (or independently of) the i18n runtime:
//
//   src/lib/appUpdate-i18n.ts  (`S`, `updateText`)  → app/lib/features/startup/generated/app_update_copy.g.dart
//
// The admission / retry copy (`src/lib/startup-i18n.ts`, `startupText`) is already generated by
// app/tool/i18n/export.mjs into app/lib/core/i18n/generated/startup_copy.g.dart and is reused as is
// (`startupText()` in core/i18n/tr.dart is a pure lookup over a const map: it works before the runtime).
// This script verifies that file is in sync with the TypeScript source instead of generating a second copy.
//
// Usage (from the repo root or app/):  node app/tool/app/gen_startup_copy.mjs [--check]
//   --check  exit 1 when a generated file is stale (CI).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '../../..');
const check = process.argv.includes('--check');

/** Evaluates the object literal assigned to `const <name>` in a TypeScript module (plain data only). */
function objectLiteral(file, name) {
  const text = readFileSync(resolve(repo, file), 'utf8');
  const start = text.search(new RegExp(`const ${name}\\b[^=]*=\\s*\\{`));
  if (start < 0) throw new Error(`${file}: const ${name} not found`);
  const open = text.indexOf('{', text.indexOf('=', start));
  let depth = 0;
  let quote = null;
  for (let i = open; i < text.length; i++) {
    const c = text[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') quote = c;
    else if (c === '{') depth++;
    else if (c === '}' && --depth === 0) {
      // Data only: no identifiers other than keys, so evaluating the literal is safe.
      return new Function(`return (${text.slice(open, i + 1)});`)();
    }
  }
  throw new Error(`${file}: unbalanced literal ${name}`);
}

const dartString = (s) => JSON.stringify(s).replace(/\$/g, '\\$');

function dartMap(map) {
  const lines = [];
  for (const [lang, entries] of Object.entries(map)) {
    const inner = Object.entries(entries).map(([k, v]) => `${dartString(k)}: ${dartString(v)}`).join(', ');
    lines.push(`  ${dartString(lang)}: {${inner}},`);
  }
  return `{\n${lines.join('\n')}\n}`;
}

function emit(target, content) {
  const path = resolve(repo, target);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current === content) return false;
  if (check) {
    console.error(`stale: ${target}`);
    return true;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`wrote ${target}`);
  return false;
}

let stale = false;

// ── appUpdate-i18n.ts ──
const updateCopy = objectLiteral('src/lib/appUpdate-i18n.ts', 'S');
stale = emit(
  'app/lib/features/startup/generated/app_update_copy.g.dart',
  `// GENERATED by app/tool/app/gen_startup_copy.mjs from src/lib/appUpdate-i18n.ts. Do not edit.
// Ported from: src/lib/appUpdate-i18n.ts
// ignore_for_file: lines_longer_than_80_chars

/// \`S\`: fixed labels of the update screens, per app language.
const Map<String, Map<String, String>> kAppUpdateCopy = ${dartMap(updateCopy)};
`,
) || stale;

// ── startup-i18n.ts: verify the shared generated map ──
const startupCopy = objectLiteral('src/lib/startup-i18n.ts', 'COPY');
const startupDart = readFileSync(resolve(repo, 'app/lib/core/i18n/generated/startup_copy.g.dart'), 'utf8');
for (const [lang, entries] of Object.entries(startupCopy)) {
  for (const [key, value] of Object.entries(entries)) {
    if (!startupDart.includes(`'${key}': ${`'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\$/g, '\\$')}'`}`)
      && !startupDart.includes(`'${key}': ${dartString(value)}`)) {
      console.error(`startup_copy.g.dart is stale for ${lang}.${key}: run node app/tool/i18n/export.mjs`);
      stale = true;
    }
  }
}

if (stale) process.exit(1);
